head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30601";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil30601.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "cal_startDate", fn: function () { return String((dma_pageContext.get("startDate") ?? "")); } },
        { childId: "cal_endDate", fn: function () { return String((dma_pageContext.get("endDate") ?? "")); } },
        { childId: "__rb0", fn: function () { return " 전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_search();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cal_startDate_onblur
 * @description cal_startDate 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_startDate_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_startDate"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30601.cal_startDate_onblur' }); }
};

/**
 * @method
 * @name cal_endDate_onblur
 * @description cal_endDate 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_endDate_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_endDate"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30601.cal_endDate_onblur' }); }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30601.btn_search_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_pageSize_onchange = function(e){
    try {
        fn_Search();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30601.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_lecrDiptList_oncellclick
 * @description grd_lecrDiptList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_lecrDiptList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_lecrDiptList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_lecrDiptList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.viewLecrDipt(r["eduApplSeq"], r["lecrDiptProcsStatNm"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_lecrDiptList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_goWrite_onclick
 * @description 「강사파견 신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goWrite_onclick = async function(e){
    try {
        await scwin.goWrite()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30601.btn_goWrite_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_92_onclick
 * @description krxpage_pagenavigator_92 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_92_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_92.page' }); } await scwin.tx_fn_search(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/issue/lecrDipt.do",
        ref: "dma_goWriteReq",
        target: "dlt_lecrDiptList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/issue/lecrDipt.do",
        ref: "dma_searchReq",
        target: "dlt_lecrDiptList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil30601.tx_fn_search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] !== null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot !== null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_92").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

/**
 * @method
 * @name tx_fn_viewLecrDipt
 * @description view Lecr Dipt 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_viewLecrDipt = async function () {
    const sbmOptions = {
        id: "tx_fn_viewLecrDipt",
        method: "post",
        action: "/issue/lecrDipt.do",
        ref: "dma_viewLecrDiptReq",
        target: "dlt_lecrDiptList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_lecrDiptList_fmt_lecrDiptProcsStatNm
 * @description grd lecr Dipt List fmt lecr Dipt Procs Stat Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_lecrDiptList_fmt_lecrDiptProcsStatNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_lecrDiptList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "lecrDiptProcsStatNm") ?? '') : '');
        if (v === '') { return "임시저장"; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "lecrDiptProcsStatNm") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_lecrDiptList.lecrDiptProcsStatNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function () {
    const frm = (document.LecrDiptForm || { elements: [] });
    frm.action = 'lecrDipt.do';
    $c.util.getComponent('dma_goWriteReq').set('method', 'writeLecrDipt');
    const nr = await scwin.tx_fn_goWrite();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30602/jldfil30602.xml", { "method": 'writeLecrDipt' });
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.LecrDiptForm || { elements: [] });
    frm.action = 'lecrDipt.do';
    $c.util.getComponent('dma_goWriteReq').set('method', 'searchLecrDipt');
    await scwin.tx_fn_search();
};

/**
 * @method
 * @name viewLecrDipt
 * @description view Lecr Dipt 처리
 * @param {*} eduApplSeq eduApplSeq
 * @param {String} lecrDiptProcsStatNm lecrDiptProcsStatNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewLecrDipt = async function (eduApplSeq, lecrDiptProcsStatNm) {
    const frm = (document.LecrDiptForm || { elements: [] });
    if (lecrDiptProcsStatNm === '') {
        $c.util.getComponent('dma_goWriteReq').set('method', 'modifyLecrDipt');
        $c.util.getComponent('dma_goWriteReq').set('modifyYn', 'Y');
    } else {
        $c.util.getComponent('dma_goWriteReq').set('method', 'viewLecrDipt');
    }
    frm.action = 'lecrDipt.do';
    $c.util.getComponent('dma_goWriteReq').set('eduApplSeq', eduApplSeq);
    const nr = await scwin.tx_fn_viewLecrDipt();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30604/jldfil30604.xml", { "method": 'modifyLecrDipt', "modifyYn": 'Y', "eduApplSeq": eduApplSeq });
    }
};
